--
-- Name: add_to_priority_queue(character varying, character varying, character varying, character varying, double precision, numeric, character varying, double precision, character varying, timestamp without time zone, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: tazara
--

CREATE FUNCTION public.add_to_priority_queue(p_order_id character varying, p_customer_name character varying, p_customer_tier character varying, p_cargo_type character varying, p_cargo_weight double precision, p_cargo_value numeric, p_route character varying, p_priority_score double precision, p_urgency_level character varying, p_delivery_deadline timestamp without time zone, p_priority_factors jsonb, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
BEGIN
        order_id, customer_name, customer_tier, cargo_type, cargo_weight,
        cargo_value, route, priority_score, urgency_level, delivery_deadline,
        priority_factors, metadata
    ) VALUES (
        p_order_id, p_customer_name, p_customer_tier, p_cargo_type, p_cargo_weight,
        p_cargo_value, p_route, p_priority_score, p_urgency_level, p_delivery_deadline,
        p_priority_factors, p_metadata
    ) ON CONFLICT (order_id) DO UPDATE SET
        priority_score = p_priority_score,
        status = 'pending',
        updated_at = CURRENT_TIMESTAMP;
    
    RETURN TRUE;
EXCEPTION
    WHEN OTHERS THEN
        RAISE NOTICE 'Error adding order to priority queue: %', SQLERRM;
        RETURN FALSE;
END;
$$;


ALTER FUNCTION public.add_to_priority_queue(p_order_id character varying, p_customer_name character varying, p_customer_tier character varying, p_cargo_type character varying, p_cargo_weight double precision, p_cargo_value numeric, p_route character varying, p_priority_score double precision, p_urgency_level character varying, p_delivery_deadline timestamp without time zone, p_priority_factors jsonb, p_metadata jsonb) OWNER TO tazara;

--
-- Name: get_priority_batch(integer, double precision); Type: FUNCTION; Schema: public; Owner: tazara
--

CREATE FUNCTION public.get_priority_batch(p_max_trains integer DEFAULT 12, p_max_cargo double precision DEFAULT 12000) RETURNS TABLE(order_ids text[], priority_scores double precision[], total_cargo_weight double precision, route_requirements jsonb, deadline_earliest timestamp without time zone, deadline_latest timestamp without time zone)
    LANGUAGE plpgsql
    AS $$
DECLARE
    batch_orders RECORD;
    remaining_trains INTEGER;
    total_weight FLOAT;
    order_list TEXT[];
    score_list FLOAT[];
    cargo_by_route JSONB;
BEGIN
    -- Initialize
    remaining_trains := p_max_trains;
    total_weight := 0;
    order_list := '{}';
    score_list := '{}';
    cargo_by_route := '{}';
    
    -- Get orders that can be handled with available trains
    FOR batch_orders IN 
        SELECT order_id, priority_score, cargo_weight, route, delivery_deadline
        FROM priority_queue
        WHERE status = 'pending'
        AND priority_score >= (SELECT CAST(config_value AS FLOAT) FROM priority_queue_config WHERE config_key = 'priority_threshold')
        ORDER BY priority_score DESC, delivery_deadline ASC
        LIMIT p_max_trains
    LOOP
        -- Check if we can handle this order
        IF remaining_trains > 0 AND total_weight + batch_orders.cargo_weight <= p_max_cargo THEN
            order_list := array_append(order_list, batch_orders.order_id);
            score_list := array_append(score_list, batch_orders.priority_score);
            total_weight := total_weight + batch_orders.cargo_weight;
            remaining_trains := remaining_trains - 1;
            
            -- Aggregate cargo by route
            cargo_by_route := cargo_by_route || 
                COALESCE(jsonb_build_object(batch_orders.route, batch_orders.cargo_weight), '{}'::jsonb);
        END IF;
    END LOOP;
    
    -- Update status of selected orders
    UPDATE priority_queue 
    SET status = 'queued', scheduled_at = CURRENT_TIMESTAMP
    WHERE order_id = ANY(order_list);
    
    -- Return results
    RETURN QUERY SELECT 
        order_list, score_list, total_weight, cargo_by_route,
        MIN(delivery_deadline) FILTER (WHERE order_id = ANY(order_list)),
        MAX(delivery_deadline) FILTER (WHERE order_id = ANY(order_list))
    FROM priority_queue
    WHERE order_id = ANY(order_list);
END;
$$;


ALTER FUNCTION public.get_priority_batch(p_max_trains integer, p_max_cargo double precision) OWNER TO tazara;

--
-- Name: schedule_maintenance(); Type: FUNCTION; Schema: public; Owner: tazara
--

CREATE FUNCTION public.schedule_maintenance() RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Update performance trends
    PERFORM update_performance_trends();
    
    -- Clean old audit logs (keep 90 days)
    DELETE FROM multi_route_audit_logs WHERE timestamp < NOW() - INTERVAL '90 days';
    
    -- Update system statistics
    ANALYZE multi_route_schedules;
    ANALYZE train_operations;
    ANALYZE route_performance;
END;
$$;


ALTER FUNCTION public.schedule_maintenance() OWNER TO tazara;

--
-- Name: update_performance_trends(); Type: FUNCTION; Schema: public; Owner: tazara
--

CREATE FUNCTION public.update_performance_trends() RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Update route efficiency trends
    SELECT 
        rp.route_name,
        CURRENT_DATE,
        AVG(rp.efficiency_score),
        SUM(rp.cargo_delivered),
        AVG(rp.efficiency_score / 50) * 100
    FROM route_performance rp
    WHERE rp.created_at >= CURRENT_DATE
    GROUP BY rp.route_name
    ON CONFLICT (route_name, metric_date) DO UPDATE SET
        average_efficiency = EXCLUDED.average_efficiency,
        total_cargo = EXCLUDED.total_cargo,
        train_utilization = EXCLUDED.train_utilization;
END;
$$;


ALTER FUNCTION public.update_performance_trends() OWNER TO tazara;

