--
-- Name: daily_performance_trends; Type: VIEW; Schema: public; Owner: tazara
--

CREATE VIEW public.daily_performance_trends AS
 SELECT date(created_at) AS performance_date,
    avg(total_cargo_delivered) AS avg_cargo,
    avg(trains_used) AS avg_trains_used,
    avg(efficiency) AS avg_efficiency,
    sum(net_profit_zmw) AS total_profit
   FROM public.performance_history
  GROUP BY (date(created_at))
  ORDER BY (date(created_at)) DESC;


ALTER VIEW public.daily_performance_trends OWNER TO tazara;

