--
-- Name: priority_queue_stats; Type: VIEW; Schema: public; Owner: tazara
--

CREATE VIEW public.priority_queue_stats AS
 SELECT count(*) AS total_orders,
    count(
        CASE
            WHEN ((status)::text = 'pending'::text) THEN 1
            ELSE NULL::integer
        END) AS pending_orders,
    count(
        CASE
            WHEN ((status)::text = 'queued'::text) THEN 1
            ELSE NULL::integer
        END) AS queued_orders,
    count(
        CASE
            WHEN ((status)::text = 'scheduled'::text) THEN 1
            ELSE NULL::integer
        END) AS scheduled_orders,
    count(
        CASE
            WHEN ((status)::text = 'completed'::text) THEN 1
            ELSE NULL::integer
        END) AS completed_orders,
    avg(priority_score) AS avg_priority_score,
    max(priority_score) AS max_priority_score,
    min(priority_score) AS min_priority_score,
    count(
        CASE
            WHEN ((urgency_level)::text = 'emergency'::text) THEN 1
            ELSE NULL::integer
        END) AS emergency_orders,
    count(
        CASE
            WHEN ((urgency_level)::text = 'urgent'::text) THEN 1
            ELSE NULL::integer
        END) AS urgent_orders,
    count(
        CASE
            WHEN ((customer_tier)::text = 'platinum'::text) THEN 1
            ELSE NULL::integer
        END) AS platinum_orders,
    count(
        CASE
            WHEN (delivery_deadline < (CURRENT_TIMESTAMP + '24:00:00'::interval)) THEN 1
            ELSE NULL::integer
        END) AS urgent_deadline_orders
   FROM public.priority_queue
  WHERE (created_at >= (CURRENT_DATE - '7 days'::interval));


ALTER VIEW public.priority_queue_stats OWNER TO tazara;

