--
-- Name: schedule_summary; Type: VIEW; Schema: public; Owner: tazara
--

CREATE VIEW public.schedule_summary AS
 SELECT schedule_id,
    "timestamp",
    num_trains,
    total_days,
    ((performance_metrics ->> 'total_cargo_delivered'::text))::numeric AS total_cargo,
    ((performance_metrics ->> 'trains_used'::text))::integer AS trains_used,
    ((performance_metrics ->> 'efficiency'::text))::numeric AS efficiency,
    ((cost_breakdown_zmw ->> 'net_profit_zmw'::text))::numeric AS net_profit_zmw,
    status
   FROM public.multi_route_schedules s
  WHERE ((status)::text = 'active'::text);


ALTER VIEW public.schedule_summary OWNER TO tazara;

